import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        long a = nextLong(), b = nextLong(), ma = nextLong(), mb = nextLong();
        long answer;
        if (ma == 0) answer = Math.min(b, mb);
        else if (mb == 0) answer = Math.min(a, ma);
        else if (a > ma * (b + 1)) answer = b + ma * (b + 1);
        else if (b > mb * (a + 1)) answer = a + mb * (a + 1);
        else answer = a + b;
        System.out.println(answer);
    }
