package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	a, b, ma, mb := nextInt(), nextInt(), nextInt(), nextInt()
	var answer int64
	switch {
	case ma == 0:
		answer = min(b, mb)
	case mb == 0:
		answer = min(a, ma)
	case a > ma*(b+1):
		answer = b + ma*(b+1)
	case b > mb*(a+1):
		answer = a + mb*(a+1)
	default:
		answer = a + b
	}
	w.WriteString(strconv.FormatInt(answer, 10) + "\n")
}
